return {
s("conv/and.hpp",{t({"// include \"./sos.hpp\"","// include \"./rsos.hpp\"","","vi andconv(vi a, vi b) {","	sos(a, 1), sos(b, 1);","	vi c(sz(a));","	rep(i, 0, sz(c)) c[i] = a[i] * b[i];","	rsos(c, 1);","	return c;","}"})}),
s("conv/or.hpp",{t({"// include \"./sos.hpp\"","// include \"./rsos.hpp\"","","vi orconv(vi a, vi b) {","	sos(a), sos(b);","	vi c(sz(a));","	rep(i, 0, sz(c)) c[i] = a[i] * b[i];","	rsos(c);","	return c;","}"})}),
s("conv/rsos.hpp",{t({"void rsos(vi &v, bool sup = 0) {","	for (int i = sz(v); i--;) for (int j = 1 << sz(v); j--;)","		if ((j >> i & 1) ^ sup) v[j] -= v[j - (1 << i)];","}"})}),
s("conv/sos.hpp",{t({"void sos(vi &v, bool sup = 0) {","	rep(i, 0, sz(v)) rep(j, 0, 1 << sz(v))","		if ((j >> i & 1) ^ sup) v[j] += v[j - (1 << i)];","}"})}),
s("ds/dsu_with_potentials.hpp",{t({"template <class S, auto op, auto inv>","struct dsu_with_potentials {","	static_assert(std::is_convertible_v<decltype(op), std::function<S(S, S)>>,","				  \"op must work as S(S, S)\");","	static_assert(std::is_convertible_v<decltype(inv), std::function<S(S)>>,","				  \"inv must work as S(S)\");","","   private:","	std::vector<int> root;","	std::vector<S> V;","","   public:","	dsu_with_potentials() {}","	dsu_with_potentials(int n, S nil) : root(n, -1), V(n, nil) {}","","	int leader(int a) {","		if (root[a] < 0) return a;","		int p = leader(root[a]);","		V[a] = op(V[a], V[root[a]]);","		return root[a] = p;","	}","","	bool merge(int a, int b, S v) {","		int a2 = leader(a), b2 = leader(b);","		if (a2 == b2) return op(V[b], inv(V[a])) == v;","		if (root[a2] > root[b2]) {","			std::swap(a2, b2);","			std::swap(a, b);","			v = inv(v);","		}","		root[a2] += root[b2];","		root[b2] = a2;","		V[b2] = op(op(v, V[a]), inv(V[b]));","		return true;","	}","","	bool same(int a, int b) { return leader(a) == leader(b); }","","	int size(int a) { return -root[leader(a)]; }","","	S potential(int a) {","		leader(a);","		return V[a];","	}","","	S voltage(int a, int b) { return op(potential(b), inv(potential(a))); }","};"})}),
s("tree/hld.hpp",{t({"struct hld {","	int n;","	vi par, dep, tin, head;","	hld(vc<vi> g, int r) : n(sz(g)), par(n), dep(n), tin(n), head(n) {","		auto dfs = [&](auto self, int a) -> int {","			int s = 1, mx = 0;","			for (int &b : g[a]) {","				erase(g[b], par[b] = a);","				dep[b] = dep[a] + 1;","				int t = self(self, b);","				s += t;","				if (t > mx) swap(b, g[a][0]), mx = t;","			}","			return s;","		};","		par[r] = r, dfs(dfs, r);","		iota(all(head), 0);","		int t = 0;","		auto dfs2 = [&](auto self, int a) -> void {","			tin[a] = t++;","			if (sz(g[a])) head[g[a][0]] = head[a];","			for (auto b : g[a]) self(self, b);","		};","		dfs2(dfs2, r);","	}","	void hl(int a, int b, auto f) {","		for (;; b = par[head[b]]) {","			if (tin[a] > tin[b]) swap(a, b);","			if (head[a] == head[b]) break;","			f(tin[head[b]], tin[b] + 1);","		}","		f(tin[a], tin[b] + 1);","	}","	int lca(int a, int b) {","		while (head[a] != head[b]) {","			int &c = dep[head[a]] > dep[head[b]] ? a : b;","			c = par[head[c]];","		}","		return dep[a] < dep[b] ? a : b;","	}","	int dist(int a, int b) { return dep[a] + dep[b] - 2 * dep[lca(a, b)]; }","	// TODO: sack","};"})}),
}
